mapper.select:
SELECT s.submission_no, s.language, s.status, CASE WHEN s.is_skipped = 1 THEN 'Skipped' ELSE s.verdict END AS verdict, s.verdict AS original_verdict, s.is_skipped AS skipped, s.score, s.submit_time, u.id AS user_id, u.username, u.nickname, cpr.sort_order AS problem_sort_order, p.pid AS problem_pid, p.title AS problem_title FROM contest_submission cs INNER JOIN submission s ON cs.submission_id = s.id INNER JOIN user_info u ON s.user_id = u.id INNER JOIN problem p ON s.problem_id = p.id LEFT JOIN contest_problem_rel cpr ON cpr.contest_id = cs.contest_id AND cpr.problem_id = s.problem_id AND cpr.is_del = 0 WHERE cs.contest_id = #{contestId} AND cs.is_del = 0 AND s.is_del = 0
AND s.user_id = #{userId}
AND p.pid = #{pid}
AND u.username = #{username}
AND s.is_skipped = 0 AND s.verdict = 'Accepted'
AND s.is_skipped = 1
AND s.is_skipped = 0 AND s.status IN ('Finished', 'Failed') AND (s.verdict IS NULL OR s.verdict <> 'Accepted')
ORDER BY s.submit_time DESC, s.id DESC

mapper.sql:
AND NOT EXISTS (SELECT 1 FROM user_capability uc WHERE uc.user_id = ${standingUserColumn} AND uc.capability = 'CONTEST_MANAGE')
AND NOT EXISTS (
    SELECT 1 FROM resource_permission rp
    WHERE rp.user_id = ${standingUserColumn}
      AND rp.resource_type = 'CONTEST' AND rp.resource_id = #{contestId}
      AND rp.permission = 'WRITE' AND rp.is_del = 0
)
AND NOT EXISTS (
    SELECT 1 FROM user_role_rel urr JOIN user_role r ON r.id = urr.role_id
    WHERE urr.user_id = ${standingUserColumn}
      AND urr.is_del = 0 AND r.is_del = 0
      AND r.role_code IN ('ADMIN', 'SUPER_ADMIN')
)
